using CompanyManagement.Api.Models;
namespace CompanyManagement.Api.Data;
public static class DevelopmentSeeder { public static async Task Seed(AppDbContext db){if(db.Clientes.Any())return;var names=new[]{"Ana Martínez","Bruno López","Carla Rivera","Diego Flores","Elena Cruz","Fernando Reyes","Gabriela Soto","Hugo Molina","Isabel Vega","Jorge Castro","Karla Díaz","Luis Pérez","María Torres","Nicolás Ramos","Olga Silva"};var clients=names.Select((name,i)=>new Cliente{Nombre=name,Email=$"cliente{i+1}@empresa.test",FechaRegistro=DateTime.UtcNow.AddDays(i<6?-(i+1):-40-i)}).ToList();db.Clientes.AddRange(clients);await db.SaveChangesAsync();db.Ordenes.AddRange(Enumerable.Range(1,40).Select(i=>new Orden{ClienteId=((i-1)%10)+1,FechaOrden=DateTime.UtcNow.AddDays(-i),MontoTotal=100+i*17.35m}));await db.SaveChangesAsync();} }
